"use client";

import { useState, useRef, useEffect } from "react";
import { 
  Send, UploadCloud, FileText, Leaf, Loader2, Info, 
  MessageSquare, Bot, User, CheckCircle2 
} from "lucide-react";

type Message = {
  role: "user" | "bot";
  content: string;
};

export default function Home() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadedFileName, setUploadedFileName] = useState<string | null>(null);
  const [chatMode, setChatMode] = useState<"simple" | "pdf">("simple");
  
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch("http://127.0.0.1:8000/upload-pdf/", {
        method: "POST",
        body: formData,
      });
      if (res.ok) {
        setUploadedFileName(file.name);
        setChatMode("pdf");
        
        // Add a system message to the chat
        setMessages((prev) => [
          ...prev, 
          { role: "bot", content: `✅ Successfully analyzed **${file.name}**. What would you like to know about this company's ESG score or carbon footprint?` }
        ]);
      } else {
        alert("Failed to upload PDF.");
      }
    } catch (error) {
      console.error("Upload error:", error);
      alert("Make sure your FastAPI server is running!");
    } finally {
      setIsUploading(false);
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;

    const userMessage = input;
    setInput("");
    setMessages((prev) => [...prev, { role: "user", content: userMessage }]);
    setIsLoading(true);

    const formData = new FormData();
    formData.append("question", userMessage);

    const endpoint =
      chatMode === "pdf" && uploadedFileName
        ? "http://127.0.0.1:8000/ask-question/"
        : "http://127.0.0.1:8000/ask-simple/";

    try {
      const res = await fetch(endpoint, {
        method: "POST",
        body: formData,
      });

      const data = await res.json();

      if (res.ok) {
        setMessages((prev) => [...prev, { role: "bot", content: data.answer }]);
      } else {
        setMessages((prev) => [...prev, { role: "bot", content: `Error: ${data.error || data.message}` }]);
      }
    } catch (error) {
      setMessages((prev) => [
        ...prev,
        { role: "bot", content: "⚠️ Failed to connect to the server. Is FastAPI running?" },
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen bg-[#f8fafc] font-sans selection:bg-emerald-200">
      
      {/* 🟢 PREMIUM DARK SIDEBAR */}
      <div className="w-[320px] bg-slate-900 text-slate-300 flex flex-col shadow-2xl z-20">
        {/* Logo Area */}
        <div className="p-6 flex items-center gap-3 border-b border-slate-800">
          <div className="p-2.5 bg-gradient-to-br from-emerald-400 to-emerald-600 rounded-xl text-white shadow-lg shadow-emerald-500/30">
            <Leaf size={24} strokeWidth={2.5} />
          </div>
          <div>
            <h1 className="text-xl font-bold text-white tracking-wide">EcoSustain<span className="text-emerald-400">.ai</span></h1>
            <p className="text-xs text-slate-500 font-medium tracking-wider uppercase mt-0.5">Enterprise Edition</p>
          </div>
        </div>

        <div className="p-6 flex flex-col gap-8 flex-1 overflow-y-auto">
          
          {/* Navigation / Modes */}
          <div className="space-y-2">
            <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-3 px-2">Analysis Modes</p>
            
            <button
              onClick={() => setChatMode("simple")}
              className={`w-full p-3.5 rounded-xl flex items-center gap-3 transition-all duration-300 ${
                chatMode === "simple" 
                  ? "bg-emerald-500/15 text-emerald-400 ring-1 ring-emerald-500/30 shadow-[inset_0_1px_0_0_rgba(255,255,255,0.1)]" 
                  : "hover:bg-slate-800 text-slate-400"
              }`}
            >
              <MessageSquare size={18} className={chatMode === "simple" ? "text-emerald-400" : "text-slate-500"} />
              <span className="font-semibold text-sm">General ESG Chat</span>
            </button>
            
            <button
              onClick={() => {
                if (!uploadedFileName) alert("Please upload a Business Profile PDF first.");
                else setChatMode("pdf");
              }}
              className={`w-full p-3.5 rounded-xl flex items-center gap-3 transition-all duration-300 ${
                chatMode === "pdf" 
                  ? "bg-emerald-500/15 text-emerald-400 ring-1 ring-emerald-500/30 shadow-[inset_0_1px_0_0_rgba(255,255,255,0.1)]" 
                  : "hover:bg-slate-800 text-slate-400"
              } ${!uploadedFileName && "opacity-60"}`}
            >
              <FileText size={18} className={chatMode === "pdf" ? "text-emerald-400" : "text-slate-500"} />
              <span className="font-semibold text-sm">Document Analysis</span>
              {uploadedFileName && <span className="ml-auto w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.8)]"></span>}
            </button>
          </div>

          {/* Upload Widget */}
          <div className="mt-auto">
            <div className={`relative rounded-2xl border-2 border-dashed p-5 transition-all duration-300 bg-slate-800/50 ${
                uploadedFileName ? "border-emerald-500/50" : "border-slate-700 hover:border-slate-500 hover:bg-slate-800"
              }`}
            >
              <div className="flex flex-col items-center text-center gap-3">
                {uploadedFileName ? (
                  <>
                    <div className="p-3 bg-emerald-500/20 rounded-full text-emerald-400">
                      <CheckCircle2 size={24} />
                    </div>
                    <div>
                      <h3 className="text-sm font-bold text-slate-200 truncate w-48">{uploadedFileName}</h3>
                      <p className="text-xs text-emerald-400 mt-1 font-medium">Ready for analysis</p>
                    </div>
                  </>
                ) : (
                  <>
                    <div className="p-3 bg-slate-800 rounded-full text-slate-400 shadow-inner">
                      <UploadCloud size={24} />
                    </div>
                    <div>
                      <h3 className="text-sm font-bold text-slate-300">Upload Report</h3>
                      <p className="text-xs text-slate-500 mt-1">PDF max 10MB</p>
                    </div>
                  </>
                )}
                
                <label className={`w-full mt-2 py-2.5 px-4 rounded-lg font-semibold text-sm text-center cursor-pointer transition-all duration-300 ${
                  isUploading 
                    ? "bg-slate-700 text-slate-400 cursor-not-allowed" 
                    : uploadedFileName 
                      ? "bg-slate-700 hover:bg-slate-600 text-slate-300" 
                      : "bg-emerald-600 hover:bg-emerald-500 text-white shadow-lg shadow-emerald-600/20"
                }`}>
                  {isUploading ? (
                    <span className="flex items-center justify-center gap-2"><Loader2 className="animate-spin" size={16} /> Parsing...</span>
                  ) : uploadedFileName ? "Upload New File" : "Select PDF File"}
                  <input type="file" accept=".pdf" className="hidden" onChange={handleFileUpload} disabled={isUploading} />
                </label>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* ⚪ MAIN CHAT AREA */}
      <div className="flex-1 flex flex-col relative bg-white bg-[radial-gradient(#e5e7eb_1px,transparent_1px)] [background-size:16px_16px]">
        
        {/* Header */}
        <div className="h-16 flex items-center px-8 border-b border-slate-100 bg-white/80 backdrop-blur-md sticky top-0 z-10">
          <div className="flex items-center gap-2">
            <span className="flex h-2 w-2 rounded-full bg-emerald-500"></span>
            <h2 className="text-sm font-bold text-slate-700 tracking-wide">
              {chatMode === "simple" ? "Global Sustainability Knowledge Base" : "Active Document Context"}
            </h2>
          </div>
        </div>

        {/* Messages Container */}
        <div className="flex-1 overflow-y-auto p-4 sm:p-8 space-y-8 scroll-smooth pb-40">
          <div className="max-w-4xl mx-auto w-full space-y-8">
            
            {messages.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-[50vh] text-center px-4">
                <div className="w-20 h-20 bg-emerald-50 rounded-3xl flex items-center justify-center mb-6 shadow-sm ring-1 ring-emerald-100 transform -rotate-6">
                  <Leaf size={40} className="text-emerald-500 rotate-6" />
                </div>
                <h2 className="text-2xl font-bold text-slate-800 mb-2">How can I help you today?</h2>
                <p className="text-slate-500 max-w-md leading-relaxed">
                  Ask me about global ESG trends, United Nations SDGs, or upload a company report for a deep-dive analysis.
                </p>
              </div>
            ) : (
              messages.map((msg, idx) => (
                <div key={idx} className={`flex gap-4 ${msg.role === "user" ? "flex-row-reverse" : "flex-row"}`}>
                  
                  {/* Avatar */}
                  <div className={`flex-shrink-0 w-10 h-10 rounded-full flex items-center justify-center shadow-sm ${
                    msg.role === "user" ? "bg-slate-800 text-white" : "bg-emerald-100 text-emerald-600 ring-1 ring-emerald-200"
                  }`}>
                    {msg.role === "user" ? <User size={18} /> : <Bot size={20} />}
                  </div>

                  {/* Message Bubble */}
                  <div className={`relative max-w-[80%] px-6 py-4 rounded-2xl text-sm md:text-base leading-relaxed ${
                    msg.role === "user"
                      ? "bg-gradient-to-br from-slate-800 to-slate-900 text-white rounded-tr-none shadow-md"
                      : "bg-white text-slate-800 border border-slate-100 rounded-tl-none shadow-[0_2px_15px_-3px_rgba(0,0,0,0.07)] whitespace-pre-wrap"
                  }`}>
                    {msg.content}
                  </div>
                </div>
              ))
            )}
            
            {/* Loading Indicator */}
            {isLoading && (
              <div className="flex gap-4 flex-row">
                <div className="flex-shrink-0 w-10 h-10 rounded-full bg-emerald-100 text-emerald-600 ring-1 ring-emerald-200 flex items-center justify-center shadow-sm">
                  <Bot size={20} />
                </div>
                <div className="bg-white border border-slate-100 px-6 py-5 rounded-2xl rounded-tl-none shadow-sm flex items-center gap-3">
                  <div className="flex gap-1">
                    <span className="w-2 h-2 bg-emerald-400 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                    <span className="w-2 h-2 bg-emerald-400 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                    <span className="w-2 h-2 bg-emerald-400 rounded-full animate-bounce"></span>
                  </div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        {/* ⌨️ FLOATING INPUT AREA */}
        <div className="absolute bottom-0 w-full bg-gradient-to-t from-white via-white to-transparent pt-10 pb-6 px-4 sm:px-8">
          <div className="max-w-4xl mx-auto w-full relative">
            <form onSubmit={handleSendMessage} className="relative flex items-center">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder={chatMode === "simple" ? "Type your message..." : "Ask about the document's carbon footprint..."}
                className="w-full bg-white border border-slate-200 text-slate-800 rounded-2xl py-4 pl-6 pr-16 shadow-[0_0_40px_rgba(0,0,0,0.04)] focus:outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500 transition-all text-base"
              />
              <button
                type="submit"
                disabled={isLoading || !input.trim()}
                className="absolute right-2 p-3 bg-emerald-500 text-white rounded-xl hover:bg-emerald-600 disabled:opacity-40 disabled:hover:bg-emerald-500 transition-all shadow-md shadow-emerald-500/20"
              >
                <Send size={20} className={input.trim() && !isLoading ? "translate-x-0.5 -translate-y-0.5 transition-transform" : ""} />
              </button>
            </form>
            
            <div className="mt-3 flex justify-center items-center gap-1.5 text-xs text-slate-400 font-medium">
              <Info size={14}/> 
              <span>EcoSustain AI can make mistakes. Always verify critical ESG metrics.</span>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
}